WITH filtered_inventory AS (SELECT * FROM inventory WHERE store_id IN (2, 3, 4)), quantity_bucket_summary AS (SELECT CASE WHEN quantity >= 248 THEN 'high' WHEN quantity >= 44 THEN 'mid' ELSE 'low' END AS quantity_bucket, COUNT(DISTINCT quantity) AS unique_stores, MAX(quantity) - MIN(quantity) AS quantity_range FROM filtered_inventory GROUP BY CASE WHEN quantity >= 248 THEN 'high' WHEN quantity >= 44 THEN 'mid' ELSE 'low' END) SELECT quantity_bucket, unique_stores, quantity_range FROM quantity_bucket_summary WHERE unique_stores >= 9 ORDER BY quantity_range, quantity_bucket LIMIT 20;
